# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['希腊 trauma，属格 traumatos','伤口；损伤']]
S=['https://www.etymonline.com/word/trauma','https://www.etymonline.com/word/traumatic','https://en.wiktionary.org/wiki/traumatize','https://www.oxfordlearnersdictionaries.com/definition/english/traumatize']
W=[
E('trauma','英 /ˈtrɔːmə/；美 /ˈtrɔmə/，亦 /ˈtraʊmə/','创伤；造成深刻伤害的经历','先想皮肤受伤后留下的伤口，再想一件事在心里留下的伤。','英语经医学拉丁语借入希腊 trauma；traumat- 是这个希腊名词在其他格形里显出的词干。',B+[['医学拉丁 trauma → 英语 trauma','身体创伤'],['心理语境中的 trauma','经历带来的深刻心理伤害']],'医院里的 physical trauma 说身体受到的损伤；childhood trauma 通常说童年经历留下的心理创伤。这个词可以指伤害本身，也可指造成伤害的事件；a trauma 常把一次经历当成可数的一件事。','physical trauma；emotional trauma；childhood trauma；experience trauma。','stress 是压力，trauma 强调创伤。经历过创伤不等于一定患有 PTSD；后者是另一个具体诊断名称，不能只凭一个词就画等号。',('The report describes the physical trauma caused by the collision.','报告描述了碰撞造成的身体损伤。'),('The novel explores how childhood trauma affects the characters as adults.','小说探讨了童年创伤怎样影响人物成年后的生活。'),sources=S+['https://www.nimh.nih.gov/health/topics/post-traumatic-stress-disorder-ptsd']),
E('traumatic','英 /trɔːˈmætɪk/；美 /trɔˈmætɪk/','造成创伤的；与创伤有关的','这段经历不是简单地让人不高兴，而是像在心里留下了一道伤口。','来自法语 traumatique、晚期拉丁 traumaticus，最终接希腊 traumatikos；现代可看出 traumat- + -ic。',B+[['希腊 traumatikos → 晚期拉丁 traumaticus／法语 traumatique','伤口相关的'],['英语 traumatic','创伤性的；令人深受打击的']],'a traumatic experience 是造成强烈冲击的经历；traumatic injury 在医学文字中是创伤性损伤。英语 traumatic 的记录比名词 trauma 更早，所以不能把它的历史写成英语先有 trauma 再加 -tic。','a traumatic event；a traumatic experience；a traumatic injury。','traumatic 常形容造成影响的事件，traumatized 常形容受到影响的人。口语有人夸张地说小事很 traumatic，正式描述时要看语境分量。',('Losing their home was a traumatic experience for the family.','失去家园给这家人带来了很深的创伤。'),('The memoir describes a traumatic period in her childhood.','这本回忆录写到了她童年一段深受打击的日子。'),sources=S),
E('traumatize','英 /ˈtrɔːmətaɪz/；美 /ˈtrɔmətaɪz/，亦 /ˈtraʊmətaɪz/','使受到创伤；使深受打击','把镜头转向伤害发生的过程：某件事伤到了一个人。','traumat- 创伤 + 动词形式 -ize；词源资料亦明确列出法语 traumatiser 的借入路线。',B+[['法语 traumatiser → 英语 traumatize','使受到创伤'],['英语心理语境','使精神上深受打击']],'这个动词有身体损伤的医学用法，日常阅读更常看到心理影响。英语常用被动式：be traumatized by something，强调人被什么事情伤到了，而不是描述他主动做了什么。','traumatize somebody；be traumatized by an experience；英国英语也写 traumatise。','frighten 可以只是吓了一跳；traumatize 语气重，通常指深刻的伤害或打击。-ize 在这里是动词形式，不是“使变成一个创伤”的机械翻译。',('The violence traumatized many of the witnesses.','那场暴力事件给许多目击者留下了心理创伤。'),('The film shows how war can traumatize people long after the fighting ends.','电影呈现了战争怎样在战斗结束很久后仍给人留下创伤。'),sources=S),
E('traumatise','/ˈtrɔːmətaɪz/','使受到创伤〔英国英语常见拼写〕','和 traumatize 是同一个动作，只是把书面上的 z 写成 s。','traumatise 对应 traumatize；-ise 与 -ize 是这个动词的拼写变体，读音仍以 /z/ 收尾。',B+[['法语 traumatiser／英语 traumatize','使受到创伤'],['英语拼写 traumatise','常见于采用 -ise 体系的英国英语']],'看到 traumatised、traumatising，也按同一词族理解。英国英语并非只允许 -ise，采用牛津拼写的出版物也会写 traumatize；切勿把拼写习惯解释成词义差别。','traumatise somebody；be traumatised by something；整篇文字保持拼写习惯一致。','traumatise 中的 s 不读 /s/。它与 traumatize 的差别是拼写，不是前者更轻、后者更重。',('The documentary examines how displacement can traumatise children.','这部纪录片探讨了流离失所怎样给儿童带来创伤。'),('The scene is disturbing, but the director said she did not intend to traumatise viewers.','这段场景令人不安，但导演说她并不想给观众留下心理创伤。'),sources=S),
E('traumatized','英 /ˈtrɔːmətaɪzd/；美 /ˈtrɔmətaɪzd/','受到创伤的；深受打击的','经历已经发生，镜头落在被它伤到的人身上。','traumatize + -ed；既是过去式、过去分词，也可作描述状态的形容词。末尾 -ed 读 /d/，不另加一整个音节。',B+[['traumatize','使受到创伤'],['traumatized','受到了创伤；处于深受打击的状态']],'She was traumatized by the attack 说她遭袭后深受创伤。a traumatized community 则把影响放大到整个群体：共同经历的事件让许多人受伤。','deeply traumatized；traumatized by something；traumatized survivors。','traumatized 是受到伤害的一方，traumatizing 是造成伤害的一方；这和 frightened/frightening 的视角差别相似。',('The survivors were still traumatized by what had happened.','幸存者仍因发生的事情深受打击。'),('The novel follows a traumatized family as they rebuild their lives.','小说跟随一个遭受创伤的家庭，讲述他们重新开始生活的过程。'),sources=S),
E('traumatised','/ˈtrɔːmətaɪzd/','受到创伤的〔英国英语常见拼写〕','同样是“人被这件事伤到了”，只是沿用 -ise 的写法。','traumatise + -ed；对应 traumatized。不要因为字母换成 s，就把 /z/ 改读成 /s/。',B+[['traumatiser／traumatise','使受到创伤'],['traumatised','受创的；深受打击的']],'英国新闻里的 traumatised witnesses 指深受打击的目击者。这个词可以作分词，也可以紧贴名词说明人物状态；它本身不交代伤害发生多久，时间要从上下文判断。','traumatised by the experience；deeply traumatised；traumatised residents。','traumatised 与 traumatized 含义相同；与 traumatic 的区别在于一个描述受影响者，一个常描述造成冲击的事。',('Residents remained traumatised months after the disaster.','灾难过去几个月后，居民仍深受创伤。'),('The play gives a voice to people traumatised by conflict.','这部戏让那些因冲突而遭受创伤的人有机会讲出自己的经历。'),sources=S),
E('traumatizing','英 /ˈtrɔːmətaɪzɪŋ/；美 /ˈtrɔmətaɪzɪŋ/','令人受到创伤的；使人深受打击的','把镜头移回事件：它正在伤害人，或者有很强的伤害作用。','traumatize 去结尾 e 加 -ing；可作现在分词，也可作形容词。',B+[['traumatize','使受到创伤'],['traumatizing','造成创伤的；正在使人受创']],'a traumatizing experience 强调经历对人的作用；the event is traumatizing the community 用进行时强调事件正在影响整个社区。它与 traumatic 常能接同类名词，但前者更明显地让人想到“使别人受到创伤”。','a traumatizing experience；emotionally traumatizing；英国英语也写 traumatising。','traumatizing 不等于 traumatized。the traumatizing event 是造成创伤的事件；the traumatized witness 是受到创伤的目击者。',('She described the evacuation as a traumatizing experience.','她说那次撤离是一段让人深受打击的经历。'),('The chapter examines the traumatizing effects of prolonged conflict.','这一章讨论了长期冲突给人造成的创伤性影响。'),sources=S)
]
ROOT=dict(id='C1537',meaning='伤口；创伤',core='TRAUM = WOUND',image='先想身体上的伤口，再想一件事在心里留下的伤：词族围绕伤害本身、造成伤害的事、受到伤害的人展开。',intro='来自希腊 trauma，属格 traumatos，因此组合里常露出 traumat-。英语先在医学中使用，后来把身体的伤口比作心理创伤。这个意象能帮助理解，但不能用一个日常用词代替具体诊断。',forms='trauma 是名词；traumatic 通过希腊、拉丁、法语词形借入，英语记录比 trauma 还早。traumatize／traumatise 是动词；-ed 强调受到影响，-ing 强调造成影响。',branches=[['伤害本身','trauma'],['创伤相关或造成创伤的','traumatic, traumatizing'],['使受到创伤','traumatize, traumatise'],['受到创伤的人或状态','traumatized, traumatised']],contrasts='stress 是压力，trauma 是创伤；traumatic experience 与 traumatized person 分别看事件和受影响的人。-ize／-ise 是拼写差别，不是不同程度的伤害。',practice='The memoir describes a traumatic experience and the people it left traumatized.\n\n这本回忆录描述了一段创伤性经历，以及因此深受打击的人们。',words=[x['word'] for x in W],exclude={'traumatophobia':'狭窄的专科恐惧名称，暂不展开'})
if __name__=='__main__':
 for name,data in [('roots_traum',[ROOT]),('words_traum',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 meta=[]
 for w,pos,en in [('traumatise','verb','To cause deep physical or psychological harm.'),('traumatised','adj','Deeply affected or hurt by a disturbing experience.'),('traumatizing','adj','Causing deep emotional harm or distress.')]:
  x=next(x for x in W if x['word']==w)
  meta.append(dict(word=w,pos=pos,ipa=x['ipa'],gloss=en,meaning_zh=x['meaning'],etymology_text='From the trauma / traumatize word family; -ise is an alternative spelling, with regular -ed and -ing forms.',sources=S))
 Path('.cache/batch200/root_traum_supplement_request.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
